// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNum, uint256 timestamp) public {
        blockNum = bound(blockNum, 1, type(uint256).max - 1);
        timestamp = bound(timestamp, 1, type(uint256).max - 2);
        address actor = address(0x1234);
        vm.deal(actor, 10 ether);
        vm.roll(blockNum);
        vm.warp(timestamp);
        vm.prank(actor);
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "fallback call failed");

        bool balanceZero = address(c).balance == 0;
        bool blockDivisibleBy15 = (blockNum % 15 == 0);
        assertTrue(balanceZero == blockDivisibleBy15);
    }
}
